#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(const float* __restrict__ input,
                               const float* __restrict__ weight,
                               float* output,
                               int batch_size, int in_channels, int out_channels,
                               int kernel_h, int kernel_w, int stride_h, int stride_w,
                               int padding_h, int padding_w, int dilation_h, int dilation_w) {
    // Global output coordinates
    const int i_out = blockIdx.y * blockDim.y + threadIdx.y;
    const int j_out = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;
    for (int oc = 0; oc < in_channels; ++oc) {
        for (int ky = 0; ky < kernel_h; ++ky) {
            int i_in = i_out * stride_h - padding_h - dilation_h * ky + oc;
            if (i_in >= 0 && i_in < input_size_h) { // need input size, approximated from x.size(2)
                for (int kx = 0; kx < kernel_w; ++kx) {
                    int j_in = j_out * stride_w - padding_w - dilation_w * kx + oc;
                    if (j_in >= 0 && j_in < input_size_w) {
                        float w_val = weight[oc * kernel_h * kernel_w + ky * kernel_w + kx];
                        sum += input[i_in + oc][j_in] * w_val;
                    }
                }
            }
        }
    }

    if (groups == 1) {
        // Write to output at index:
        float out_idx = ((i_out * out_channels + oc) * out_h * out_w +
                         (j_out * out_w + j_out) * out_channels +
                         oc * out_h * out_w +
                         i_out * out_w + j_out);
        output[out_idx] = sum;
    }
}

torch::Tensor conv2d_cuda(torch::Tensor x, int in_channels, int out_channels,
                          std::array<int64_t, 2> kernel_size,
                          std::array<int64_t, 2> stride = {1, 1},
                          std::array<int64_t, 2> padding = {0, 0},
                          std::array<int64_t, 2> dilation = {1, 1},
                          int groups) -> torch::Tensor {
    // Compute output dimensions
    int H_in = x.size(2);
    int W_in = x.size(3);
    int out_h = (H_in + 2 * padding[0] - kernel_size[0] * dilation[0]) / stride[0] + 1;
    int out_w = (W_in + 2 * padding[1] - kernel_size[1] * dilation[1]) / stride[1] + 1;

    // Allocate output tensor
    torch::Tensor out = torch::zeros({x.size(0), out_channels, out_h, out_w}, torch::float);

    const int block_size = 256;
    const int num_blocks_x = (out_w + block_size - 1) / block_size;
    const int num_blocks_y = (out_h + block_size - 1) / block_size;

    conv2d_kernel<<<num_blocks_x, block_size, 0, 0>>>(x.data_ptr<float>(), weight_ptr, out.data_ptr<float>(),
                                                      x.size(0), in_channels, out_channels,
